package com.gomgomapps.math.core;
import java.util.*;import java.util.regex.*;
/** One-step book contexts; mental and learner-authored written methods share the same public answer. */
public final class ContextCalculationMethods {
 private ContextCalculationMethods(){}
 public static final String ID="contextCalculationMethods";
 public static final Catalog.Skill SKILL=new Catalog.Skill(ID,"문장제의 계산 방법",6,1,1,"",ID,1000000,"add1000,sub1000,tables,divide","문제의 수량 관계를 파악하고 암산이나 식 쓰기를 선택해 답을 구한다.");
 private static final String[] PREFIX={"보관소에 책이 %d권 있습니다. 책 %d권을 더 가져왔습니다.\n책은 모두 몇 권입니까?","보관소에 책이 %d권 있습니다. 책 %d권을 다른 곳으로 보냈습니다.\n남은 책은 몇 권입니까?","각 보관소에 책이 %d권씩 있습니다. 보관소는 %d곳입니다.\n책은 모두 몇 권입니까?","책 %d권을 보관소 %d곳에 똑같이 나눠 보관합니다.\n한 보관소의 책은 몇 권입니까?"};
 private static final String[] READ_TEMPLATES={PREFIX[0],PREFIX[1],PREFIX[2],PREFIX[3],"한 상자에 책이 %d권씩 들어 있습니다. 상자는 %d개입니다.\n책은 모두 몇 권입니까?","책 %d권을 상자 %d개에 똑같이 나눠 담습니다.\n한 상자에 책을 몇 권씩 담습니까?"};
 private static final Pattern[] PATTERNS=Arrays.stream(READ_TEMPLATES).map(s->Pattern.compile(Pattern.quote(s).replace("%d","\\E([0-9]{1,7})\\Q"))).toArray(Pattern[]::new);
 public record Givens(int operation,int a,int b,long answer){public String expression(){return a+new String[]{"+","-","*","/"}[operation]+b;}}
 public static Givens read(Question q){if(q==null||!ID.equals(q.skillId)||q.prompt==null)return null;for(int index=0;index<PATTERNS.length;index++){int op=index<4?index:index-2;Matcher m=PATTERNS[index].matcher(q.prompt);if(!m.matches())continue;int a=Integer.parseInt(m.group(1)),b=Integer.parseInt(m.group(2));if(a>1000000||b>1000000||op==1&&a<b||op==3&&(b==0||a%b!=0))return null;long answer=switch(op){case 0->(long)a+b;case 1->a-b;case 2->(long)a*b;default->a/b;};if(answer>1000000)return null;return new Givens(op,a,b,answer);}return null;}
 static Question make(int op,int a,int b){if(op<0||op>3||a<0||b<0)throw new IllegalArgumentException();Question q=new Question(ID,String.format(Locale.ROOT,PREFIX[op],a,b),"");Givens g=read(q);if(g==null)throw new IllegalArgumentException("context domain");q.expression=g.expression();q.answers=new String[]{""+g.answer};q.labels=new String[]{"답"};q.stepSupport=true;attach(q);return q;}
 public static Question workQuestion(Question q){Givens g=read(q);if(g==null)return null;return new Question(ID,q.prompt,g.expression(),""+g.answer);}
 private record Product(int divisor,long start,long end){}
 private record Domain(int maximum,List<Product>products,long productsCount,long divisionCount,long pairs){}
 private static Domain cached;
 private static synchronized Domain domain(int max){if(cached!=null&&cached.maximum==max)return cached;List<Product>p=new ArrayList<>();long count=max+1L;for(int b=1;b<=Math.min(99,max);b++){long end=count+max/b+1L;p.add(new Product(b,count,end));count=end;}return cached=new Domain(max,List.copyOf(p),count,count-max-1L,(max+1L)*(max+2L)/2);}
 private static int[] pair(long index){int lo=0,hi=1000000;while(lo<hi){int mid=lo+(hi-lo+1)/2;if((long)mid*(mid+1)/2<=index)lo=mid;else hi=mid-1;}return new int[]{lo,(int)(index-(long)lo*(lo+1)/2)};}
 private static Question at(Domain d,int op,long index){if(op<2){int[]v=pair(index);return op==0?make(0,v[1],v[0]-v[1]):make(1,v[0],v[1]);}if(op==3)index+=d.maximum+1L;if(index<=d.maximum)return make(2,(int)index,0);int lo=0,hi=d.products.size()-1;while(lo<hi){int mid=(lo+hi)/2;if(index<d.products.get(mid).end)hi=mid;else lo=mid+1;}Product p=d.products.get(lo);int a=(int)(index-p.start);return op==2?make(2,a,p.divisor):make(3,a*p.divisor,p.divisor);}
 static Question next(Random r,CurriculumLimits limits,Map<String,Integer>recent){Domain d=domain(limits.givenMaximum(1000000));int op=r.nextInt(d.divisionCount==0?3:4);long size=op<2?d.pairs:op==2?d.productsCount:d.divisionCount;Question q=IndexedQuestionSupply.chooseLarge(size,i->at(d,op,i),r,limits,recent);if(!recent.containsKey(q.signature()))return q;long total=2*d.pairs+d.productsCount+d.divisionCount;return IndexedQuestionSupply.chooseLarge(total,i->{if(i<d.pairs)return at(d,0,i);i-=d.pairs;if(i<d.pairs)return at(d,1,i);i-=d.pairs;if(i<d.productsCount)return at(d,2,i);return at(d,3,i-d.productsCount);},r,limits,recent);}
 static Checker.Result check(Question q,List<String>answers){Givens g=read(q);if(g==null||answers==null||answers.size()!=1||answers.get(0)==null||!answers.get(0).trim().matches("[0-9]{1,7}"))return new Checker.Result(Checker.Status.INPUT_NEEDED,0,"답 입력 필요");return Long.parseLong(answers.get(0).trim())==g.answer?new Checker.Result(Checker.Status.CORRECT,-1,"정답"):new Checker.Result(Checker.Status.WRONG_ANSWER,0,"이 답 확인");}
 public static void attach(Question q){Givens g=read(q);if(g==null)return;StudyGuide h=new StudyGuide().transfer(false);h.teachingVersion="context-calculation-methods-v1";h.step("문제의 첫째 수를 쓰세요.","첫째 수 = ","",""+g.a).step("문제의 둘째 수를 쓰세요.","둘째 수 = ","",""+g.b).step("문제의 수량 관계에 맞게 계산하세요.",g.a+" "+new String[]{"+","−","×","÷"}[g.operation]+" "+g.b+" = ","",""+g.answer);q.studyGuide=h;}
}
